<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\CashService;
use EventMenu\Services\ConfiguredOrderService;
use EventMenu\Services\OperatingUnitService;
use EventMenu\Services\OrderHistoryService;
use EventMenu\Services\PaymentService;
use EventMenu\Services\ProductionService;
use EventMenu\Services\StockReservationService;

Auth::requirePermission('orders.create');
$tenantId=em_require_tenant();
$unit=(new OperatingUnitService())->requireCurrent();$unitId=(int)$unit['id'];
$cartKey='pos_cart_'.$tenantId.'_'.$unitId;
if(!isset($_SESSION[$cartKey])||!is_array($_SESSION[$cartKey]))$_SESSION[$cartKey]=[];
$cart=&$_SESSION[$cartKey];$configured=new ConfiguredOrderService();
function pos_flatten_options(mixed$value):array{$out=[];$walk=function($v)use(&$out,&$walk){if(is_array($v)){foreach($v as$x)$walk($x);return;}$id=(int)$v;if($id>0)$out[]=$id;};$walk($value);$out=array_values(array_unique($out));sort($out);return$out;}
$cashService=Auth::can('cash.manage')?new CashService():null;$cashSession=$cashService?->currentSession();

if($_SERVER['REQUEST_METHOD']==='POST'){
 em_post_csrf();$action=(string)($_POST['action']??'');
 if($action==='add'){
  try{$id=(int)($_POST['product_id']??0);$qty=max(1,min(99,(int)($_POST['qty']??1)));$optionIds=pos_flatten_options($_POST['option_ids']??[]);$resolved=$configured->resolveLine($pdo,$tenantId,['product_id'=>$id,'qty'=>$qty,'option_ids'=>$optionIds],false);$lineKey=hash('sha256',$id.':'.implode(',',$resolved['option_ids']));if(isset($cart[$lineKey]))$cart[$lineKey]['qty']=min(99,(float)$cart[$lineKey]['qty']+$qty);else$cart[$lineKey]=['product_id'=>$id,'qty'=>$qty,'option_ids'=>$resolved['option_ids']];em_go('pos');}catch(Throwable$e){em_flash('error',$e->getMessage());em_go('pos');}
 }
 if($action==='remove'){unset($cart[(string)($_POST['line_key']??'')]);em_go('pos');}
 if($action==='clear'){$cart=[];em_go('pos');}
 if($action==='create'){
  if(!$cart)exit('Adicione itens ao pedido.');$channel=(string)($_POST['channel']??'counter');if(!in_array($channel,['counter','pickup','table','delivery'],true))exit('Canal inválido.');$tableId=(int)($_POST['table_id']??0);$name=trim((string)($_POST['customer_name']??''));$phone=trim((string)($_POST['customer_phone']??''));$address=trim((string)($_POST['delivery_address']??''));$notes=mb_substr(trim((string)($_POST['notes']??'')),0,1000);$settle=(string)($_POST['settle']??'later');if(!in_array($settle,['later','cash'],true))exit('Forma de recebimento inválida.');if($channel==='delivery'&&($name===''||$phone===''||$address===''))exit('Delivery exige nome, telefone e endereço.');if($settle==='cash'&&(!Auth::can('payments.manage')||!Auth::can('cash.manage')))exit('Seu perfil não pode receber pagamentos.');
  try{$result=Database::transaction(function(PDO$tx)use($tenantId,$unitId,$cart,$channel,$tableId,$name,$phone,$address,$notes,$settle,$configured):array{
   $tabId=null;$validTableId=null;if($channel==='table'){$t=$tx->prepare(Database::portableSql($tx,'SELECT id,status FROM restaurant_tables WHERE id=? AND tenant_id=? AND unit_id=? FOR UPDATE'));$t->execute([$tableId,$tenantId,$unitId]);$table=$t->fetch();if(!$table||$table['status']==='inactive')throw new RuntimeException('Mesa inválida para esta unidade.');$tab=$tx->prepare(Database::portableSql($tx,'SELECT id FROM tabs WHERE tenant_id=? AND table_id=? AND status="open" ORDER BY id DESC LIMIT 1 FOR UPDATE'));$tab->execute([$tenantId,$tableId]);$tabId=$tab->fetchColumn();if($tabId===false)throw new RuntimeException('Abra uma comanda para esta mesa antes de lançar o pedido.');$validTableId=$tableId;}
   $customerId=null;if($name!==''){$existing=null;if($phone!==''){$c=$tx->prepare('SELECT id FROM customers WHERE tenant_id=? AND phone=? ORDER BY id DESC LIMIT 1');$c->execute([$tenantId,$phone]);$existing=$c->fetchColumn();}if($existing!==false&&$existing!==null)$customerId=(int)$existing;else{$c=$tx->prepare('INSERT INTO customers (tenant_id,name,phone) VALUES (?,?,?)');$c->execute([$tenantId,$name,$phone?:null]);$customerId=(int)$tx->lastInsertId();}}
   $items=[];$total=0;foreach(array_values($cart)as$line){$resolved=$configured->resolveLine($tx,$tenantId,$line,true);$total+=(int)$resolved['total_cents'];$items[]=$resolved;}if($total<=0)throw new RuntimeException('Pedido sem valor válido.');
   $token=bin2hex(random_bytes(20));$o=$tx->prepare('INSERT INTO orders (public_token,tenant_id,unit_id,customer_id,channel,status,payment_status,subtotal_cents,total_cents,table_id,tab_id,delivery_address,notes,created_by) VALUES (?,?,?,?,?,"confirmed","unpaid",?,?,?,?,?,?,?)');$o->execute([$token,$tenantId,$unitId,$customerId,$channel,$total,$total,$validTableId,$tabId,$channel==='delivery'?$address:null,$notes?:null,Auth::id()]);$orderId=(int)$tx->lastInsertId();$i=$tx->prepare('INSERT INTO order_items (order_id,product_id,name_snapshot,unit_price_cents,quantity,total_cents) VALUES (?,?,?,?,?,?)');foreach($items as$item){$i->execute([$orderId,$item['product_id'],$item['name'],$item['unit_price_cents'],$item['quantity'],$item['total_cents']]);$configured->persistModifiers($tx,$tenantId,$orderId,(int)$tx->lastInsertId(),$item);}
   (new StockReservationService())->reserve($tx,$tenantId,$orderId,$items,null);(new ProductionService())->ensureOrderJobs($tx,$tenantId,$orderId,Auth::id());(new OrderHistoryService())->record($tx,$tenantId,$orderId,null,'confirmed','pos','Pedido criado no PDV da unidade #'.$unitId.'. Origem: '.$channel.'.',Auth::id());Auth::audit('order.created_pos','order',(string)$orderId,['unit_id'=>$unitId,'channel'=>$channel,'total_cents'=>$total,'configured_lines'=>count($items)]);
   if($settle==='cash'){$cash=new CashService();$session=$cash->currentSession();if(!$session)throw new RuntimeException('Abra seu turno de caixa antes de receber dinheiro.');if($session['unit_id']!==null&&(int)$session['unit_id']!==$unitId)throw new RuntimeException('Seu caixa está aberto em outra unidade.');$payments=new PaymentService();$payment=$payments->create($orderId,'manual','pos-cash:'.$tenantId.':'.$unitId.':'.$orderId.':'.bin2hex(random_bytes(8)));$payments->confirmVerified(['tenant_id'=>$tenantId,'order_id'=>$orderId,'provider'=>'manual','provider_payment_id'=>'CASH-POS-'.strtoupper(bin2hex(random_bytes(8))),'amount_cents'=>$total,'currency'=>'BRL','account_reference'=>'manual']);$cash->recordPaidPayment((int)$payment['id'],'cash');Auth::audit('payment.cash_pos','order',(string)$orderId,['unit_id'=>$unitId]);}
   return['order_id'=>$orderId,'paid'=>$settle==='cash'];
  });$cart=[];$orderId=(int)$result['order_id'];em_flash('ok',$result['paid']?'Pedido #'.$orderId.' criado e recebido. Produção e QR foram gerados.':'Pedido #'.$orderId.' criado. Confirme o pagamento antes da retirada.');em_go('orders',['view'=>$orderId]);}catch(Throwable$e){em_flash('error',$e->getMessage());em_go('pos');}
 }
}

$p=$pdo->prepare('SELECT p.*,c.name category_name,COALESCE(ui.stock_qty,0) unit_stock_qty,COALESCE(ui.average_cost_cents,p.average_cost_cents,0) unit_average_cost_cents,EXISTS(SELECT 1 FROM product_recipes r WHERE r.tenant_id=p.tenant_id AND r.product_id=p.id) has_recipe FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN unit_inventory ui ON ui.tenant_id=p.tenant_id AND ui.product_id=p.id AND ui.unit_id=? WHERE p.tenant_id=? AND p.active=1 ORDER BY c.sort_order,c.name,p.name');$p->execute([$unitId,$tenantId]);$products=$p->fetchAll();
$modifierCatalog=$configured->catalogModifiers($pdo,$tenantId,array_column($products,'id'));
$t=$pdo->prepare('SELECT rt.id,rt.name,t.id tab_id,t.label FROM restaurant_tables rt JOIN tabs t ON t.table_id=rt.id AND t.status="open" WHERE rt.tenant_id=? AND rt.unit_id=? AND rt.status<>"inactive" ORDER BY rt.name');$t->execute([$tenantId,$unitId]);$tables=$t->fetchAll();
$categories=[];foreach($products as$product){$cat=(string)($product['category_name']??'Outros');$categories[$cat]=true;}
$cartRows=[];$cartTotal=0;$invalid=[];foreach($cart as$lineKey=>$line){try{$r=$configured->resolveLine($pdo,$tenantId,$line,false);$mods=[];foreach($r['modifiers']as$m)$mods[]=$m['group_name'].': '.$m['name'];$cartTotal+=(int)$r['total_cents'];$cartRows[]=['line_key'=>$lineKey,'name'=>$r['name'],'qty'=>$r['quantity'],'line'=>$r['total_cents'],'mods'=>$mods];}catch(Throwable){$invalid[]=$lineKey;}}foreach($invalid as$key)unset($cart[$key]);if($invalid)em_flash('error','Um item configurado foi alterado e saiu do carrinho. Adicione novamente.');

em_header('Caixa / PDV','pos');
?>
<style>
.pos-shell{display:grid;grid-template-columns:minmax(0,1.82fr) minmax(325px,.64fr);gap:13px;align-items:start}.pos-toolbar{display:flex;gap:7px;overflow:auto;padding:1px 0 10px;scrollbar-width:none}.pos-toolbar::-webkit-scrollbar{display:none}.pos-chip{min-height:35px;border:1px solid var(--em-border);background:#fff;color:var(--em-text);padding:7px 11px;border-radius:999px;white-space:nowrap;font-size:11px;font-weight:800;cursor:pointer}.pos-chip.active{background:var(--em-primary);color:var(--em-primary-ink);border-color:var(--em-primary)}.pos-products{display:grid;grid-template-columns:repeat(auto-fill,minmax(165px,1fr));gap:8px}.pos-product{display:flex;flex-direction:column;min-height:142px;padding:12px!important;border-radius:13px!important}.pos-product h3{font-size:15px;line-height:1.2;margin:5px 0}.pos-product>span,.pos-product>small{font-size:11px}.pos-product .price{font-size:18px;font-weight:900;color:var(--em-primary);margin-top:auto}.pos-product form{margin-top:8px}.pos-product .actions{display:grid;grid-template-columns:54px 1fr;gap:6px}.pos-product .actions input{min-height:38px;padding:6px;text-align:center}.pos-product .actions button{min-height:38px}.pos-cart{position:sticky;top:18px;padding:16px}.pos-cart-line{padding:9px 0;border-bottom:1px solid var(--em-border)}.pos-cart-line strong{font-size:13px}.pos-cart-total{display:flex;align-items:center;justify-content:space-between;margin:13px 0;padding:13px 14px;border:1px solid #d9cff9;background:linear-gradient(135deg,#f7f4ff,var(--em-primary-soft));border-radius:13px;color:var(--em-text)}.pos-cart-total span{font-size:11px;color:var(--em-muted);font-weight:800;text-transform:uppercase;letter-spacing:.06em}.pos-cart-total strong{font-size:27px;letter-spacing:-.6px}.pos-channel-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.pos-channel{position:relative}.pos-channel input{position:absolute;opacity:0}.pos-channel span{display:block;border:1px solid var(--em-border);border-radius:11px;padding:10px;background:#fff;min-height:66px}.pos-channel b,.pos-channel small{display:block}.pos-channel b{font-size:12px}.pos-channel small{color:var(--em-muted);font-size:11px;margin-top:3px}.pos-channel input:checked+span{border-color:var(--em-primary);box-shadow:0 0 0 3px rgba(98,54,223,.09);background:var(--em-primary-soft)}.pos-modifiers{border-top:1px solid var(--em-border);margin-top:8px;padding-top:8px}.pos-modifiers summary{cursor:pointer;color:var(--em-primary);font-size:11px;font-weight:800}.pos-mod-group{padding:8px 0;border-bottom:1px solid var(--em-border)}.pos-mod-title,.pos-mod-option{display:flex;justify-content:space-between;gap:8px}.pos-mod-title{font-size:11px}.pos-mod-option{padding:5px 0;font-size:11px}.pos-mod-option input{width:auto;min-height:0}.cart-mods{font-size:11px;color:var(--em-muted);line-height:1.4;margin-top:3px}.pos-unit-banner{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}.pos-unit-banner strong{font-size:14px}.pos-submit{min-height:56px!important;font-size:15px!important;border-radius:12px!important;box-shadow:0 10px 24px color-mix(in srgb,var(--em-primary) 25%,transparent)!important}
@media(max-width:950px){.pos-shell{grid-template-columns:1fr}.pos-cart{position:static}.pos-products{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:700px){.pos-products{grid-template-columns:repeat(2,minmax(0,1fr))}.pos-unit-banner{align-items:flex-start;flex-direction:column}.pos-unit-banner input{max-width:none!important;width:100%}}
@media(max-width:390px){.pos-products{grid-template-columns:1fr 1fr;gap:6px}.pos-product{min-height:136px;padding:10px!important}.pos-product h3{font-size:14px}.pos-product .price{font-size:16px}.pos-channel-grid{grid-template-columns:1fr}.pos-cart-total strong{font-size:24px}}
</style>
<section class="page-hero"><div><span class="eyebrow">PDV · <?=Security::e(mb_strtoupper($unit['name']))?></span><h2>Venda rápida</h2><p>Mais produtos na tela, menos cliques. Estoque, cozinha, caixa e QR continuam vinculados à unidade atual.</p></div><div class="hero-actions"><a class="button secondary" href="<?=Security::e(app_url('?route=orders'))?>">Pedidos</a><a class="button secondary" href="<?=Security::e(app_url('?route=pickup'))?>">Retirada / QR</a></div></section>
<?php if(Auth::can('cash.manage')&&!$cashSession):?><div class="alert warning">Seu caixa está fechado. Você pode criar para pagar depois; para receber dinheiro, abra o turno de caixa.</div><?php endif;?>
<div class="pos-shell"><section><div class="pos-unit-banner"><div><span class="muted">Unidade atual</span><br><strong><?=Security::e($unit['name'])?></strong></div><input id="pos-search" type="search" placeholder="Buscar produto..." style="max-width:280px"></div><div class="pos-toolbar" id="pos-categories"><button class="pos-chip active" type="button" data-cat="">Todos</button><?php foreach(array_keys($categories)as$cat):?><button class="pos-chip" type="button" data-cat="<?=Security::e(mb_strtolower($cat))?>"><?=Security::e($cat)?></button><?php endforeach;?></div><div class="pos-products" id="pos-products"><?php foreach($products as$p):$out=(int)$p['track_stock']&&!(int)$p['has_recipe']&&(float)$p['unit_stock_qty']<=0;$mods=$modifierCatalog[(int)$p['id']]??[];$cat=(string)($p['category_name']??'Outros');?><article class="card pos-product" data-product data-cat="<?=Security::e(mb_strtolower($cat))?>" data-search="<?=Security::e(mb_strtolower($p['name'].' '.($p['sku']??'')))?>"><span class="muted"><?=Security::e($cat)?></span><h3><?=Security::e($p['name'])?></h3><?php if($p['track_stock']&&!(int)$p['has_recipe']):?><small class="muted">Disponível: <?=Security::e((string)$p['unit_stock_qty'])?></small><?php elseif((int)$p['has_recipe']):?><small class="muted">Ficha técnica ativa</small><?php endif;?><div class="price"><?=em_money($p['price_cents'])?></div><form method="post"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><?php if($mods):?><details class="pos-modifiers"><summary>Personalizar</summary><?php foreach($mods as$g):$min=max((int)$g['min_select'],(int)$g['required']?1:0);$max=max(1,(int)$g['max_select']);?><div class="pos-mod-group"><div class="pos-mod-title"><strong><?=Security::e($g['name'])?><?= $min>0?' *':''?></strong><span class="muted"><?= $min>0?'mín '.$min:'opcional'?> · máx <?=$max?></span></div><?php foreach($g['options']as$o):?><label class="pos-mod-option"><span><input type="checkbox" name="option_ids[<?=(int)$g['id']?>][]" value="<?=(int)$o['id']?>"> <?=Security::e($o['name'])?></span><strong><?= (int)$o['price_delta_cents']===0?'incluído':((int)$o['price_delta_cents']>0?'+ ':'- ').em_money(abs((int)$o['price_delta_cents']))?></strong></label><?php endforeach;?></div><?php endforeach;?></details><?php endif;?><div class="actions"><input type="number" name="qty" min="1" max="99" value="1"<?=$out?' disabled':''?>><button class="primary"<?=$out?' disabled':''?>><?=$out?'Esgotado':'Adicionar'?></button></div></form></article><?php endforeach;?></div></section><aside class="card pos-cart"><div class="section-head"><div><span class="eyebrow">PEDIDO</span><h2>Carrinho</h2></div><?php if($cartRows):?><form method="post"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="clear"><button class="secondary compact">Limpar</button></form><?php endif;?></div><?php if(!$cartRows):?><div class="empty-state"><strong>Carrinho vazio</strong><span>Toque em um produto para começar.</span></div><?php else:?><?php foreach($cartRows as$i):?><div class="pos-cart-line"><div class="section-head"><div><strong><?=Security::e((string)$i['qty'])?>× <?=Security::e($i['name'])?></strong><?php if($i['mods']):?><div class="cart-mods"><?=Security::e(implode(' · ',$i['mods']))?></div><?php endif;?><div><?=em_money($i['line'])?></div></div><form method="post"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="line_key" value="<?=Security::e($i['line_key'])?>"><button class="secondary compact">×</button></form></div></div><?php endforeach;?><div class="pos-cart-total"><span>Total do pedido</span><strong><?=em_money($cartTotal)?></strong></div><form method="post" class="form-grid" id="pos-order-form"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="create"><div class="span-2"><span class="field-title">Como será atendido?</span><div class="pos-channel-grid"><label class="pos-channel"><input type="radio" name="channel" value="counter" checked><span><b>Balcão / PDV</b><small>QR para conferência.</small></span></label><label class="pos-channel"><input type="radio" name="channel" value="pickup"><span><b>Retirada</b><small>Cliente apresenta QR.</small></span></label><label class="pos-channel"><input type="radio" name="channel" value="table"><span><b>Mesa / comanda</b><small>Sem QR de retirada.</small></span></label><label class="pos-channel"><input type="radio" name="channel" value="delivery"><span><b>Delivery</b><small>Entrega no endereço.</small></span></label></div></div><label class="span-2" id="pos-table-wrap" hidden>Mesa / comanda<select name="table_id"><option value="0">Escolha</option><?php foreach($tables as$table):?><option value="<?=(int)$table['id']?>"><?=Security::e($table['name'].' · '.$table['label'])?></option><?php endforeach;?></select></label><label>Cliente<input name="customer_name" placeholder="Nome"></label><label>Telefone<input name="customer_phone" placeholder="WhatsApp"></label><label class="span-2" id="pos-address-wrap" hidden>Endereço de entrega<input name="delivery_address" placeholder="Rua, número, bairro"></label><label class="span-2">Observações<textarea name="notes" placeholder="Observações gerais"></textarea></label><label class="span-2">Recebimento<select name="settle"><option value="later">Pagar depois / online</option><?php if(Auth::can('payments.manage')&&Auth::can('cash.manage')):?><option value="cash">Dinheiro agora</option><?php endif;?></select></label><button class="primary span-2 pos-submit">Criar pedido · <?=em_money($cartTotal)?></button></form><?php endif;?></aside></div>
<script>const search=document.getElementById('pos-search');let activeCat='';function filterPos(){const q=(search?.value||'').trim().toLocaleLowerCase('pt-BR');document.querySelectorAll('[data-product]').forEach(el=>{el.hidden=!!((activeCat&&el.dataset.cat!==activeCat)||(q&&!el.dataset.search.includes(q)))})}search?.addEventListener('input',filterPos);document.querySelectorAll('.pos-chip').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.pos-chip').forEach(b=>b.classList.remove('active'));btn.classList.add('active');activeCat=btn.dataset.cat||'';filterPos()}));const radios=document.querySelectorAll('input[name="channel"]'),tableWrap=document.getElementById('pos-table-wrap'),addressWrap=document.getElementById('pos-address-wrap');function channelUi(){const v=document.querySelector('input[name="channel"]:checked')?.value;tableWrap.hidden=v!=='table';addressWrap.hidden=v!=='delivery'}radios.forEach(r=>r.addEventListener('change',channelUi));channelUi();</script>
